def evaluate_rpn_safe(tokens: list[str]) -> int | str:
    if not tokens:
        return "ERROR:INVALID"
    stack: list[int] = []
    for token in tokens:
        if token in ('+', '-', '*', '/'): 
            if len(stack) < 2:
                return "ERROR:INVALID"
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:
                if b == 0:
                    return "ERROR:DIV_BY_ZERO"
                stack.append(int(a / b))
        else:
            digits = token[1:] if token.startswith(('+', '-')) else token
            if not digits.isdigit():
                return "ERROR:INVALID"
            stack.append(int(token))
    if len(stack) != 1:
        return "ERROR:INVALID"
    return stack[0]

